    "name": "get_core_entity",
    "description": "Liest eine Core-Entitaet vollstaendig (Text, Status, Herkunft, Historie).",
    "parameters": {
      "type": "object",
      "properties": {
        "entityId": {
          "type": "string"
        }
      },
      "required": [
        "entityId"
      ]
    }
  },
  {
    "type": "function",
    "name": "list_open_decisions",
    "description": "Listet offene Entscheidungen (DEC-*, status=open_decision) mit dem widersprochenen Ziel. Pruefen, BEVOR du CONTRADICT vorschlaegst - ist der Widerspruch schon erfasst, nutze ALREADY_DECIDED.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "search_core",
    "description": "Sucht in den Core-Requirements nach Stichworten (entityId/text).",
    "parameters": {
      "type": "object",
      "properties": {
        "query": {
          "type": "string"
        },
        "limit": {
          "type": "integer",
          "default": 30
        }
      },
      "required": [
        "query"
      ]
    }
  },
  {
    "type": "function",
    "name": "search_rejections",
    "description": "Sucht in frueher ABGELEHNTEN Vorschlaegen (Wiedervorlage-Wissen, REJ-*). Ohne query: alle. Ist ein eingehendes Requirement inhaltlich gleich, relatedRejectionId auf der Operation setzen \u2014 trotzdem normal vorschlagen, der Mensch entscheidet.",
